package fetch

import (
	"context"
	"time"
)

// FetchAll processes ids in order (50ms each) and returns their results.
// When ctx is cancelled it must STOP PROMPTLY and return the results
// gathered so far - but it currently ignores ctx entirely.
func FetchAll(ctx context.Context, ids []int) []int {
	out := []int{}
	for _, id := range ids {
		time.Sleep(50 * time.Millisecond)
		out = append(out, id*10)
	}
	return out
}

