package fetch

import (
	"context"
	"testing"
	"time"
)

func TestUncancelledReturnsAll(t *testing.T) {
	got := FetchAll(context.Background(), []int{1, 2, 3})
	want := []int{10, 20, 30}
	if len(got) != 3 || got[0] != want[0] || got[2] != want[2] {
		t.Fatalf("FetchAll = %v, want %v", got, want)
	}
}

func TestCancellationIsPrompt(t *testing.T) {
	ids := make([]int, 50) // 2.5s of work if cancellation is ignored
	for i := range ids {
		ids[i] = i + 1
	}
	ctx, cancel := context.WithTimeout(context.Background(), 120*time.Millisecond)
	defer cancel()

	start := time.Now()
	got := FetchAll(ctx, ids)
	elapsed := time.Since(start)

	if elapsed > 600*time.Millisecond {
		t.Fatalf("returned after %v - cancellation ignored (must stop promptly)", elapsed)
	}
	if len(got) == 0 {
		t.Fatalf("partial results were dropped: got 0 items")
	}
	if len(got) >= len(ids) {
		t.Fatalf("got all %d items despite a 120ms budget", len(got))
	}
	if got[0] != 10 {
		t.Fatalf("partial results wrong: %v", got[:1])
	}
}

