package fetch

import (
	"context"
	"time"
)

// FetchAll processes ids in order (50ms each) and returns their results.
// When ctx is cancelled it stops promptly and returns the results so far.
func FetchAll(ctx context.Context, ids []int) []int {
	out := []int{}
	for _, id := range ids {
		select {
		case <-ctx.Done():
			return out
		case <-time.After(50 * time.Millisecond):
			out = append(out, id*10)
		}
	}
	return out
}

